begin;
do $$
declare p public.players%rowtype; q public.players%rowtype; coach uuid; e uuid:=gen_random_uuid(); other_e uuid:=gen_random_uuid(); a uuid:=gen_random_uuid(); n integer; val numeric;
begin
 select * into strict p from public.players where active and profile_id is not null and team_id is not null limit 1;
 select * into strict q from public.players where active and profile_id is not null and team_id=p.team_id and id<>p.id limit 1;
 select id into strict coach from public.profiles where club_id=p.club_id and active and role in ('coach','administrator') limit 1;
 insert into public.events(id,club_id,team_id,event_type,title,starts_at,ends_at) values(e,p.club_id,p.team_id,'training','Temporary manual RPE test',now()-interval '3 hours',now()-interval '1 hour'),(other_e,p.club_id,p.team_id,'training','Temporary attendance RPE test',now()-interval '3 hours',now()-interval '1 hour');
 perform set_config('request.jwt.claim.sub',coach::text,true);
 insert into public.attendance(event_id,player_id,official_status,effective_minutes) values(e,p.id,'present',120);
 perform set_config('request.jwt.claim.sub',coach::text,true);execute 'set local role authenticated';
 perform public.record_player_rpe(e,p.id,6,30);
 select score into val from public.rpe_entries where event_id=e and player_id=p.id and source='coach_for_player' and recorded_by=coach;if val<>6 then raise exception 'manual RPE failed';end if;
 if not exists(select 1 from public.attendance where event_id=e and player_id=p.id and effective_minutes=30) then raise exception 'individual minutes failed';end if;
 perform public.record_player_rpe(e,p.id,7,40);select count(*) into n from public.rpe_entries where event_id=e and player_id=p.id;if n<>1 then raise exception 'duplicate RPE';end if;
 begin perform public.record_player_rpe(other_e,p.id,5,30);raise exception 'unconfirmed attendance accepted';exception when raise_exception then if SQLERRM='unconfirmed attendance accepted' then raise;end if;end;
 begin perform public.record_player_rpe(e,p.id,11,30);raise exception 'bad RPE accepted';exception when raise_exception then if SQLERRM='bad RPE accepted' then raise;end if;end;
 begin perform public.record_player_rpe(e,p.id,5,130);raise exception 'too many minutes accepted';exception when raise_exception then if SQLERRM='too many minutes accepted' then raise;end if;end;
 insert into public.attendance(event_id,player_id,official_status,effective_minutes) values(other_e,p.id,'present',120);
 update public.events set team_id=null where id=other_e;
 begin perform public.record_player_rpe(other_e,p.id,5,30);raise exception 'teamless event accepted';exception when raise_exception then if SQLERRM='teamless event accepted' then raise;end if;end;
 insert into public.additional_player_loads(id,player_id,activity_type,context,starts_at,duration_minutes,score) values(a,p.id,'match','Juvenil test',now()-interval '5 hours',60,8);
 begin insert into public.additional_player_loads(id,player_id,activity_type,context,starts_at,duration_minutes,score) values(gen_random_uuid(),p.id,'match','Juvenil test',now()-interval '5 hours',60,8);raise exception 'duplicate additional accepted';exception when unique_violation then null;end;
 begin insert into public.additional_player_loads(id,player_id,activity_type,context,starts_at,duration_minutes,score) values(gen_random_uuid(),p.id,'match','Future',now()+interval '1 hour',60,8);raise exception 'future accepted';exception when raise_exception then if SQLERRM='future accepted' then raise;end if;end;
 begin update public.additional_player_loads set recorded_by=q.profile_id where id=a;raise exception 'spoof accepted';exception when insufficient_privilege then null;end;
 execute 'reset role';update public.rpe_entries set source='player',recorded_by=null where event_id=e and player_id=p.id;
 perform set_config('request.jwt.claim.sub',coach::text,true);execute 'set local role authenticated';
 begin perform public.record_player_rpe(e,p.id,3,20);raise exception 'player response overwritten';exception when raise_exception then if SQLERRM='player response overwritten' then raise;end if;end;
 select score into val from public.rpe_entries where event_id=e and player_id=p.id;if val<>7 then raise exception 'player score changed';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',p.profile_id::text,true);execute 'set local role authenticated';
 select count(*) into n from public.additional_player_loads where id=a;if n<>1 then raise exception 'own activity not visible';end if;
 update public.additional_player_loads set score=1 where id=a;get diagnostics n=row_count;if n<>0 then raise exception 'player update allowed';end if;
 begin perform public.record_player_rpe(e,p.id,3,20);raise exception 'player RPC allowed';exception when raise_exception then if SQLERRM='player RPC allowed' then raise;end if;end;
 begin insert into public.additional_player_loads(id,player_id,activity_type,context,starts_at,duration_minutes,score) values(gen_random_uuid(),p.id,'match','Forbidden',now()-interval '5 hours',60,8);raise exception 'player insert allowed';exception when insufficient_privilege then null;end;
 execute 'reset role';perform set_config('request.jwt.claim.sub',q.profile_id::text,true);execute 'set local role authenticated';
 select count(*) into n from public.additional_player_loads where id=a;if n<>0 then raise exception 'teammate activity visible';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',coach::text,true);execute 'set local role authenticated';
 update public.additional_player_loads set voided=true where id=a;if not exists(select 1 from public.additional_player_loads where id=a and voided) then raise exception 'annul failed';end if;
 execute 'reset role';execute 'set local role anon';begin perform 1 from public.additional_player_loads;raise exception 'anon read allowed';exception when insufficient_privilege then null;end;execute 'reset role';
end $$;
select 'PASS: atomic manual RPE/minutes, duplicate prevention, own-response protection, additional activities, future/invalid inputs, staff provenance, private player reads, player/anon write restrictions, annulment' as result;
rollback;
